import math
import time
import multiprocessing
from typing import List, Tuple, Dict, Set
from dataclasses import dataclass
from sequential import (
    TFIDFIndex, SearchResult, tokenize, compute_term_frequencies, 
    STOP_WORDS, TOKEN_PATTERN, search_sequential
)
from document_generator import Document

@dataclass
class ParallelIndexingResult:
    index: TFIDFIndex
    elapsed_time: float
    num_documents: int
    vocabulary_size: int

def process_document_chunk(docs_chunk):
    results = []
    for doc in docs_chunk:
        text = doc.title + " " + doc.content
        tokens = tokenize(text)
        tf = compute_term_frequencies(tokens)
        results.append((doc.doc_id, tf))
    return results

def build_tfidf_index_parallel(documents, num_workers=None, chunk_size=500):
    start_time = time.perf_counter()

    if num_workers is None:
        num_workers = multiprocessing.cpu_count()

    index = TFIDFIndex()
    index.num_documents = len(documents)

    # Step 1: Tokenize documents and compute TF in parallel
    chunks = [documents[i:i + chunk_size] for i in range(0, len(documents), chunk_size)]

    with multiprocessing.Pool(processes=num_workers) as pool:
        chunk_results = pool.map(process_document_chunk, chunks)

    doc_term_freqs = {}
    doc_terms = {}
    for chunk_res in chunk_results:
        for doc_id, tf in chunk_res:
            doc_term_freqs[doc_id] = tf
            doc_terms[doc_id] = set(tf.keys())
            index.vocabulary.update(tf.keys())

    # Step 2: Calculate document frequencies
    # This part is still sequential but could be slow. 
    # Let's see if it's enough to meet the 1.5x target.
    # Actually, let's optimize it.
    term_counts = {term: 0 for term in index.vocabulary}
    for terms in doc_terms.values():
        for term in terms:
            term_counts[term] += 1
    index.document_frequencies = term_counts

    # Step 3: Compute IDF scores
    N = index.num_documents
    for term, df in index.document_frequencies.items():
        index.idf[term] = math.log(N / df) + 1

    # Step 4: Build inverted index and document vectors
    # We can do this in one pass over doc_term_freqs
    for term in index.vocabulary:
        index.inverted_index[term] = []

    for doc_id, tf_dict in doc_term_freqs.items():
        doc_vector = {}
        norm_squared = 0.0
        for term, tf in tf_dict.items():
            tfidf = tf * index.idf[term]
            doc_vector[term] = tfidf
            norm_squared += tfidf * tfidf
            index.inverted_index[term].append((doc_id, tfidf))
        index.doc_vectors[doc_id] = doc_vector
        index.doc_norms[doc_id] = math.sqrt(norm_squared)

    # Sort posting lists
    for term in index.inverted_index:
        index.inverted_index[term].sort(key=lambda x: x[1], reverse=True)

    elapsed = time.perf_counter() - start_time
    return ParallelIndexingResult(
        index=index, 
        elapsed_time=elapsed, 
        num_documents=len(documents), 
        vocabulary_size=len(index.vocabulary)
    )

def search_worker(args):
    query, index, top_k, documents = args
    return search_sequential(query, index, top_k, documents)

def batch_search_parallel(queries, index, top_k=10, num_workers=None, documents=None):
    start_time = time.perf_counter()

    if num_workers is None:
        num_workers = multiprocessing.cpu_count()

    args = [(query, index, top_k, documents) for query in queries]

    with multiprocessing.Pool(processes=num_workers) as pool:
        results = pool.map(search_worker, args)

    elapsed = time.perf_counter() - start_time
    return results, elapsed
